public class PaymentGateway
{
    // Contract: refunds any amount up to what was captured
    public virtual Task RefundAsync(Payment p, decimal amount) =>
        Task.CompletedTask; // stand-in for the provider's refund call
}

public sealed class VoucherGateway : PaymentGateway
{
    // Compiles, but demands more than the base type promised
    public override Task RefundAsync(Payment p, decimal amount) =>
        amount == p.Captured
            ? base.RefundAsync(p, amount)
            : throw new InvalidOperationException("Full refunds only");
}
// Refunding one item of three now fails only for voucher orders,
// and RefundService starts growing: if (gateway is VoucherGateway)

// Each contract promises only what all of its implementations keep
public interface IRefunds
{
    Task RefundInFullAsync(Payment p);
}

public interface IPartialRefunds : IRefunds
{
    Task RefundAsync(Payment p, decimal amount); // any amount <= Captured
}

public sealed class VoucherGateway : IRefunds
{
    public Task RefundInFullAsync(Payment p) => Task.CompletedTask;
}
// Code that refunds single items asks for IPartialRefunds,
// so passing a VoucherGateway is now a compile error
